package com.bookstore.controller; import com.bookstore.entity.Author; import com.bookstore.service.AuthorService;  import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; @Controller @RequestMapping("/authors") public class AuthorController{private final AuthorService service;public AuthorController(AuthorService s){service=s;}@GetMapping String list(Model m){m.addAttribute("items",service.findAll());return "authors/list";}@GetMapping("/new")String create(Model m){m.addAttribute("item",new Author());return "authors/form";}@GetMapping("/edit/{id}")String edit(@PathVariable Long id,Model m){m.addAttribute("item",service.findById(id));return "authors/form";}@PostMapping("/save")String save(@Valid @ModelAttribute("item") Author item,BindingResult r){if(r.hasErrors())return "authors/form";service.save(item);return "redirect:/authors";}@GetMapping("/delete/{id}")String delete(@PathVariable Long id){service.delete(id);return "redirect:/authors";}}